{
  "stops": [
    {
      "poi_id": "p101",
      "kind": "activity",
      "must_do_id": null,
      "note": "Duck through the river-side aisles of chợ Hàn (Hàn market, the central market by the river) and sniff out the dried squid and sesame crackers."
    },
    {
      "poi_id": "p82",
      "kind": "activity",
      "must_do_id": null,
      "note": "Stroll the seaward lawns of East Sea Park and let the onshore breeze reset your travel head."
    },
    {
      "poi_id": "p165",
      "kind": "meal",
      "must_do_id": null,
      "note": "Grab a stool at Chả Bò Bà Quýt and let the charred beef rolls do the talking. Ngon quá (so tasty)."
    },
    {
      "poi_id": "p258",
      "kind": "activity",
      "must_do_id": null,
      "note": "Wait for the dragon to breathe fire over the water; from the bridge you get the best view of its scales."
    }
  ]
}
```

