      "poi_id": "p211",
      "kind": "activity",
      "must_do_id": null,
      "note": "Old yellow walls, silk lanterns, slow corners. Give it the whole morning and let the town set the pace."
    },
    {
      "poi_id": "p123",
      "kind": "meal",
      "must_do_id": null,
      "note": "Crispy turmeric pancake, herbs in one hand, rice paper in the other. Roll, dip, repeat."
    },
    {
      "poi_id": "p208",
      "kind": "activity",
      "must_do_id": null,
      "note": "The little bridge with the temple on top. Cross it slowly, the wood has stories."
    },
    {
      "poi_id": "p16",
      "kind": "activity",
      "must_do_id": null,
      "note": "Soft sand, gentle waves, a beach chair with your name on it. This is the easy part of the day."
    },
    {
      "poi_id": "p230",
      "kind": "activity",
      "must_do_id": null,
      "note": "Lanterns and old Hội An life staged under the evening sky. Stay for the lights on the water."
    },
    {
      "poi_id": "p31",
      "kind": "meal",
      "must_do_id": null,
      "note": "A quiet table after the show. The vegetarian set here is a gentle way to end the day."
